import numpy as np
o=run(X); dec=o.argmax(1)
def rate(pred): return (pred==dec).mean().round(3)
srt=np.argsort(X,1)
for k in range(1,9):
    print('kth largest k=%d'%k, rate(srt[:,-k]))
for k in range(1,9):
    print('kth smallest', rate(srt[:,k-1]))
# argmax of suffix of length L
for L in [2,3,4,5,6,7,8]:
    print('argmax last',L, rate(X[:,-L:].argmax(1)+8-L))
for L in [1,2,3,4,5,6,7]:
    print('argmax first',L, rate(X[:,:L].argmax(1)))
